mapper.update:
UPDATE transcript SET file_key=#{fileKey}, generation=#{generation}, byte_offset=#{byteOffset},
  anchor_hash=#{anchorHash}, observed_size=#{observedSize}, modified_at=#{modifiedAt}, scanned_at=#{scannedAt}
WHERE id=#{id}

mapper.insert:
INSERT INTO transcript_item(transcript_id, transcript_path, generation, byte_offset, end_offset,
  content_hash, raw_bytes, raw_text, parse_status, item_type, event_time, ingested_at)
SELECT #{sourceId}, path, #{generation}, #{byteOffset}, #{endOffset}, #{contentHash}, #{rawBytes},
  #{rawText}, #{parseStatus}, #{eventType}, #{eventTime}, #{ingestedAt}
FROM transcript WHERE id=#{sourceId}

mapper.select:
SELECT id, transcript_id source_id, generation, byte_offset, end_offset, content_hash, raw_bytes,
  raw_text, parse_status, item_type event_type, event_time, ingested_at
FROM transcript_item WHERE id > #{afterId}
AND transcript_id = #{sourceId}
AND parse_status = #{parseStatus}
ORDER BY id LIMIT #{limit}

SELECT * FROM execution_normalization_job
WHERE status = 'PENDING' AND available_at <= #{now}
ORDER BY id LIMIT 1

mapper.update:
UPDATE execution_session SET transcript_path=#{transcriptPath}, started_at=#{startedAt}, ended_at=#{endedAt},
  state=#{state}, last_observed_at=#{lastObservedAt}, version=#{revision}
WHERE session_id_sha256=UNHEX(SHA2(#{sessionId}, 256)) AND session_id=#{sessionId}
  AND version=#{revision}-1

UPDATE execution_turn SET title=#{title}, model=#{model}, working_directory=#{workingDirectory},
  started_at=#{startedAt}, ended_at=#{endedAt}, state=#{state}, version=#{revision}
WHERE session_id_sha256=UNHEX(SHA2(#{sessionId}, 256)) AND session_id=#{sessionId}
  AND turn_id_sha256=UNHEX(SHA2(#{turnId}, 256)) AND turn_id=#{turnId} AND version=#{revision}-1

UPDATE execution_tool_call SET tool_name=#{toolName}, pre_observed_at=#{preObservedAt}, post_observed_at=#{postObservedAt},
  state=#{state}, estimated_duration_ms=#{estimatedDurationMs}, duration_valid=#{durationValid}, version=#{revision}
WHERE session_id_sha256=UNHEX(SHA2(#{sessionId}, 256)) AND session_id=#{sessionId}
  AND turn_id_sha256=UNHEX(SHA2(#{turnId}, 256)) AND turn_id=#{turnId}
  AND tool_use_id_sha256=UNHEX(SHA2(#{toolUseId}, 256)) AND tool_use_id=#{toolUseId}
  AND version=#{revision}-1

mapper.select:
SELECT t.session_id, t.turn_id, t.started_at, t.ended_at, t.state, s.transcript_path, COALESCE(t.title,'等待用户问题内容补齐') title, t.model, t.working_directory cwd, b.path_status transcript_path_status,b.session_check_status, (SELECT COUNT(*) FROM execution_tool_call x WHERE x.session_id=t.session_id AND x.turn_id=t.turn_id) tool_count, (SELECT SUM(estimated_duration_ms) FROM execution_tool_call x WHERE x.session_id=t.session_id AND x.turn_id=t.turn_id AND duration_valid=1) tool_ms, 0 otel_tool_count, CASE WHEN t.started_at IS NOT NULL AND t.ended_at >= t.started_at THEN t.ended_at-t.started_at END duration_ms FROM execution_turn t JOIN execution_session s ON s.session_id=t.session_id LEFT JOIN transcript b ON b.meta_session_id=t.session_id
WHERE lower(t.session_id) LIKE CONCAT('%', lower(#{query}), '%') OR lower(t.turn_id) LIKE CONCAT('%', lower(#{query}), '%')
ORDER BY COALESCE(t.started_at, 0) DESC, t.turn_id LIMIT #{limit} OFFSET #{offset}
